}

export function slugifyTitle(title: string, cardSeparator: CardSeparator) {
    const slug = title
        .trim()
        .toLowerCase()
        .replace(/[^a-z0-9]+/gu, cardSeparator)
        .replace(new RegExp(`^[${escapeRegExp(cardSeparator)}]|[${escapeRegExp(cardSeparator)}]$`, 'gu'), '')

    return slug.length > 0 ? slug : DEFAULT_TITLE_SLUG
}

/** Card file names keep their id and the separator style they were created with. */
const CARD_FILE_NAME_PATTERN = /^([A-Za-z][A-Za-z0-9]*)([-_])(\d+)\2(.+)\.md$/u

function splitPath(path: string) {
    const separatorIndex = path.lastIndexOf('/')

    return separatorIndex === -1
        ? { directory: '', fileName: path }
        : { directory: path.slice(0, separatorIndex), fileName: path.slice(separatorIndex + 1) }
}

/**
 * Resolves the file path a card should live at for `title`, keeping its id, folder and separator style.
 * Returns `currentPath` when the name cannot be parsed as a card file or the target is already taken.
 */
export function desiredCardPath(currentPath: string, title: string, occupiedPaths: Iterable<string>) {
    const normalizedPath = currentPath.replace(/\\/gu, '/')
    const { directory, fileName } = splitPath(normalizedPath)
    const match = fileName.match(CARD_FILE_NAME_PATTERN)
    if (!match) return currentPath

    const [, idPrefix, separator, number] = match
    const cardSeparator = separator as CardSeparator
    const titleSlug = slugifyTitle(title, cardSeparator)
    const nextFileName = `${idPrefix}${separator}${number}${separator}${titleSlug}${MARKDOWN_EXTENSION}`
    const desiredPath = directory.length > 0 ? `${directory}/${nextFileName}` : nextFileName
    if (desiredPath === normalizedPath) return currentPath

    const sourcePathKey = normalizedPath.toLowerCase()
    const taken = [...occupiedPaths]
        .map((path) => path.replace(/\\/gu, '/').toLowerCase())
        .some((path) => path !== sourcePathKey && path === desiredPath.toLowerCase())

    return taken ? currentPath : desiredPath
}

function getCardTypeConfig(cardTypes: CardTypeConfig[], draft: CardDraft) {
    const cardTypeConfig = cardTypes.find((config) => config.type === draft.type)

    if (!cardTypeConfig) throw new Error(`Missing card type config: ${draft.type}`)

    return cardTypeConfig
}

export function getNextCardNumber(files: MarkdownFile[], idPrefix: string) {
    const idPattern = new RegExp(`(?:^|/)${escapeRegExp(idPrefix)}[-_](\\d+)[-_].+\\.md$`, 'u')
    const numbers = files
        .map((file) => file.path.match(idPattern)?.[1])
        .filter((number): number is string => !!number)
        .map((number) => Number.parseInt(number, 10))

    return numbers.length > 0 ? Math.max(...numbers) + 1 : 1
}

function buildCardBody(template: string, draft: CardDraft) {
    if (draft.bodyIncludesTemplate) return draft.body

    const hasDraftBody = draft.body.trim().length > 0

    return hasDraftBody ? `${template}\n\n${draft.body}` : template
}

export function createCardFile(
    files: MarkdownFile[],
    workingFolder: string,
    cardSeparator: CardSeparator,
    cardTypes: CardTypeConfig[],
    cardBodyTemplate: string,
    initialState: string,
    draft: CardDraft,
): MarkdownFile {
    const cardTypeConfig = getCardTypeConfig(cardTypes, draft)
    const number = getNextCardNumber(files, cardTypeConfig.idPrefix)
    const id = buildCardId(cardTypeConfig.idPrefix, number, cardSeparator)
    const titleSlug = slugifyTitle(draft.title, cardSeparator)
    const internalId = markdownParsingService.generateInternalId()
    const content = markdownParsingService.buildCardMarkdown(
        { affects: [], id, internalId, policy: {}, status: initialState, title: draft.title },
        buildCardBody(cardBodyTemplate, draft),
    )

    return {
        content,
        path: `${workingFolder}/${id}${cardSeparator}${titleSlug}${MARKDOWN_EXTENSION}`,
    }
}


---OPERATIONS---
import { createCardFile } from '../../data/card_naming'
import { computeMove, type CardMoveUpdate } from '../../data/card_ordering'
import type { CardDraft, MarkdownFile } from '../../data/data_types'
import type { OpenDocumentSaveReference } from '../open_files_service'
import { telemetryService } from '../telemetry/telemetry_service'
import { CardArchiveOperations } from './card_archive_operations'
import { CardInternalIdOperations } from './card_internal_id_operations'
import {
    attachSaveReference,
    CardOperationContext,
    type CardOperationsDeps,
    type CommitRequest,
} from './card_operation_context'
import { CardRenameOperations } from './card_rename_operations'
import { markdownParsingService } from './markdown_parsing_service'
import { ProjectFileOperations } from './project_file_operations'

export type { CardOperationsDeps }

/** The card-facing surface of the data service, delegating to focused operation modules. */
export class CardOperations {
    private readonly context: CardOperationContext
    private readonly archives: CardArchiveOperations
    private readonly internalIds: CardInternalIdOperations
    private readonly projectFiles: ProjectFileOperations
    private readonly renames: CardRenameOperations
    private readonly triggerStateActions: (cardPath: string, state: string) => void

    constructor(
        dependencies: CardOperationsDeps,
        triggerStateActions: (cardPath: string, state: string) => void,
    ) {
        this.context = new CardOperationContext(dependencies)
        this.triggerStateActions = triggerStateActions
        this.archives = new CardArchiveOperations(this.context, triggerStateActions)
        this.renames = new CardRenameOperations(this.context)
        this.internalIds = new CardInternalIdOperations(this.context, () => this.renames.reset())
        this.projectFiles = new ProjectFileOperations(this.context)
    }

    async createCard(draft: CardDraft, initialState: string) {
        const { config, project } = this.context.requireProject('create a card')
        const { dependencies } = this.context

        const file = createCardFile(
            dependencies.files(),
            config.workingFolder,
            config.cardSeparator,
            config.cardTypes,
            config.cardBodyTemplate,
            initialState,
            draft,
        )
        dependencies.replaceFiles([...dependencies.files(), file], config.workingFolder)
        await this.context.commitAndMergeFiles({
            branch: project.branch,
            files: [file],
            message: `Create ${file.path}`,
        }, [file])
        await this.context.pushCreatedItem('Card')

        dependencies.refreshSnapshot(config.workingFolder)
        telemetryService.trackEvent('create_card')

        return file
    }

    createFolder(parentDirectory: string, name: string) {
        return this.projectFiles.createFolder(parentDirectory, name)
    }

    createMarkdownFile(parentDirectory: string, name: string) {
        return this.projectFiles.createMarkdownFile(parentDirectory, name)
    }

    updateCardBody(path: string, body: string, saveReference?: OpenDocumentSaveReference) {
        const existingFile = this.context.dependencies.requireFile(path)

        return this.saveFile(
            { content: markdownParsingService.replaceBody(existingFile.content, body), path, sha: existingFile.sha },
            saveReference,
        )
    }

    updateCardAffects(path: string, affects: string[]) {
        return this.context.saveCardContentChange(path, (content) => markdownParsingService.setAffects(content, affects))
    }

    updateCardHeaderFields(path: string, updates: Record<string, string>, saveReference?: OpenDocumentSaveReference) {
        return this.context.saveCardContentChange(
            path,
            (content) => markdownParsingService.rewriteHeader(content, updates),
            saveReference,
        )
    }

    updateCardWorktree(path: string, worktree: number | null) {
        return this.context.saveCardContentChange(path, (content) => markdownParsingService.setWorktree(content, worktree))
    }

    toggleCardPolicy(path: string, policyKey: string, saveReference?: OpenDocumentSaveReference) {
        const { config } = this.context.dependencies.requireDependencies()
        const existingFile = this.context.dependencies.requireFile(path)
        const card = markdownParsingService.parseCard(existingFile, config.workingFolder)
        const enabled = card.header.policy[policyKey] ?? false

        return this.context.saveCardContentChange(
            path,
            (content) => markdownParsingService.setPolicyFlag(content, policyKey, !enabled),
            saveReference,
        )
    }

    ensureCardInternalIds() {
        return this.internalIds.ensureCardInternalIds()
    }

    updateCardTitle(path: string, title: string, saveReference?: OpenDocumentSaveReference) {
        return this.renames.updateCardTitle(path, title, saveReference)
    }

    async moveCard(cardPath: string, targetStatus: string, targetIndex: number) {
        if (targetStatus === 'archived') return this.archives.archiveCard(cardPath, targetIndex)

        const activeCards = this.context.dependencies.snapshot()?.activeCards ?? []
        const movedCard = activeCards.find((card) => card.path === cardPath)
        const previousStatus = movedCard?.header.status ?? null
        const updates = computeMove(activeCards, cardPath, targetStatus, targetIndex)

        this.saveCardMoveUpdates(cardPath, updates)

        if (movedCard && previousStatus !== targetStatus) this.triggerStateActions(movedCard.path, targetStatus)

        return updates
    }

    /** Applies every ordering link from one move to local state and one persistence batch. */
    private saveCardMoveUpdates(cardPath: string, updates: CardMoveUpdate[]) {
        if (updates.length === 0) return

        const { commitBatcher, project } = this.context.requireProject('move a card')
        const openDocumentsByPath = new Map(updates.map(({ path }) => [path, this.context.findOpenCardDocument(path)]))
        const updatedFiles = this.context.applyOrderingUpdates(updates)
        this.context.replaceUpdatedFiles(updatedFiles)

        const changes = updatedFiles.map((file) => attachSaveReference(
            file,
            this.context.resyncOpenCardDocument(openDocumentsByPath.get(file.path) ?? null, file.path, undefined, 'Moved'),
        ))
        commitBatcher.schedule(project.branch, changes, `Move ${cardPath}`)
        this.context.dependencies.dispatchChanged()
    }

    async deleteCard(path: string) {
        const card = this.context.dependencies.snapshot()?.activeCards.find((currentCard) => currentCard.path === path)
        if (!card) throw new Error(`Cannot delete an active card that is not loaded: ${path}`)

        return this.projectFiles.deleteProjectFile(path, true)
    }

    async deleteFile(path: string) {
        const { dependencies } = this.context
        const loadedFile = dependencies.files().some((file) => file.path === path)
        const repositoryFile = dependencies.snapshot()?.repositoryFiles.includes(path) ?? false
        if (!loadedFile && !repositoryFile) throw new Error(`Cannot delete a file that is not loaded: ${path}`)

        const activeCard = dependencies.snapshot()?.activeCards.some((card) => card.path === path) ?? false

        return this.projectFiles.deleteProjectFile(path, activeCard)
    }

    deleteFolder(path: string) {
        return this.projectFiles.deleteFolder(path)
    }

    saveFile(file: MarkdownFile, saveReference?: OpenDocumentSaveReference) {
        return this.context.saveFile(file, saveReference)
    }

    saveProjectFile(file: MarkdownFile, message: string) {
        return this.projectFiles.saveProjectFile(file, message)
    }

    flushPendingCommits() {
        return this.context.flushPendingCommits()
    }

    commitFiles(request: CommitRequest) {
        return this.context.commitFiles(request)
    }

    pushCommittedFiles(request: CommitRequest) {
        return this.context.pushCommittedFiles(request)
    }

    commitAndMergeFiles(request: CommitRequest, fallbackFiles: MarkdownFile[] = []) {
        return this.context.commitAndMergeFiles(request, fallbackFiles)
    }
}


---RENAME---
import { desiredCardPath } from '../../data/card_naming'
import type { MarkdownFile } from '../../data/data_types'
import type { OpenDocumentSaveReference } from '../open_files_service'
import { attachSaveReference, type CardOperationContext } from './card_operation_context'
import { markdownParsingService } from './markdown_parsing_service'

/**
 * Card title edits and the file renames they trigger. Renames are serialized per card and
 * flushed on their own so a move never shares a commit batch entry with another edit.
 */
export class CardRenameOperations {
    private readonly context: CardOperationContext
    /** Tracks where renamed cards landed so queued title updates keep targeting the same card. */
    private readonly committedPathsByPath = new Map<string, string>()
    private readonly titleChainByPath = new Map<string, Promise<void>>()

    constructor(context: CardOperationContext) {
        this.context = context
    }

    /** Drops rename tracking that only applies to the previously open project. */
    reset() {
        this.committedPathsByPath.clear()
    }

    /** Saves the new title and, when it changes the card file name, renames the file. */
    async updateCardTitle(path: string, title: string, saveReference?: OpenDocumentSaveReference) {
        const pending = this.titleChainByPath.get(path) ?? Promise.resolve()
        const applyTitle = async () => this.applyCardTitle(this.committedPath(path), title, saveReference)
        const titleUpdate = pending.then(applyTitle, applyTitle)
        const chained = titleUpdate.then(() => undefined, () => undefined)
        this.titleChainByPath.set(path, chained)
        void chained.then(() => {
            if (this.titleChainByPath.get(path) === chained) this.titleChainByPath.delete(path)
        })

        return titleUpdate
    }

    private async applyCardTitle(path: string, title: string, saveReference?: OpenDocumentSaveReference) {
        const { dependencies } = this.context
        const existingFile = dependencies.requireFile(path)
        const file = {
            content: markdownParsingService.setCardTitle(existingFile.content, title),
            path,
            ...(existingFile.sha ? { sha: existingFile.sha } : {}),
        }
        const snapshot = dependencies.snapshot()
        const occupiedPaths = [
            ...dependencies.files().map((currentFile) => currentFile.path),
            ...(snapshot?.repositoryFiles ?? []),
        ]
        const targetPath = desiredCardPath(path, title, occupiedPaths)
        if (targetPath === path) return this.context.saveCardMetadataFile(file, saveReference)

        return this.renameCardFile(file, targetPath, saveReference)
    }

    /** Commits pending work, then commits the rename on its own so no other change shares its batch entry. */
    private async renameCardFile(file: MarkdownFile, targetPath: string, saveReference?: OpenDocumentSaveReference) {
        const { dependencies } = this.context
        const { commitBatcher, project } = this.context.requireProject('rename a card')

        await this.context.flushPendingCommits()

        const existingFile = dependencies.requireFile(file.path)
        const openDocument = this.context.findOpenCardDocument(file.path)
        const { content } = this.context.mergeOpenCardBody(file)
        const renamedFile = { content, path: targetPath, ...(existingFile.sha ? { sha: existingFile.sha } : {}) }

        // replaceUpdatedFiles already rebuilds the snapshot; the file keeps its old path until the move is committed.
        this.context.replaceUpdatedFiles([{ ...existingFile, content }])
        const documentSaveReference = this.context.resyncOpenCardDocument(openDocument, file.path, saveReference, 'Renamed')
        commitBatcher.schedulePathChange(
            project.branch,
            file.path,
            attachSaveReference(renamedFile, documentSaveReference),
            `Rename ${file.path} to ${targetPath}`,
            (fromPath, toPath) => this.reconcileCardPath(fromPath, toPath),
        )
        dependencies.dispatchChanged()
        await this.context.flushPendingCommits()

        return renamedFile
    }

    /** Moves local state onto the committed path and lets path-keyed callers follow the card. */
    private reconcileCardPath(fromPath: string, toPath: string) {
        if (fromPath === toPath) return

        const { dependencies } = this.context
        const { config } = dependencies.requireDependencies()
        dependencies.renameFile(fromPath, toPath, config.workingFolder)
        for (const [sourcePath, currentPath] of this.committedPathsByPath) {
            if (currentPath === fromPath) this.committedPathsByPath.set(sourcePath, toPath)
        }
        this.committedPathsByPath.set(fromPath, toPath)
        dependencies.cardPathChanged(fromPath, toPath)
        dependencies.dispatchChanged()
    }

    private committedPath(path: string) {
        return this.committedPathsByPath.get(path) ?? path
    }
}

